// ============================================================
// HEIC/HEIF Conversion Check + EXIF Metadata Extraction
// ============================================================
const items = $input.all();
const results = [];

for (const item of items) {
  const fileName = item.json.name || item.json.fileName || 'unknown';
  const mimeType = item.json.mimeType || '';
  const fileId = item.json.id || item.json.fileId || '';
  const fileSize = item.json.size || 0;

  const isHeic = /\.(heic|heif)$/i.test(fileName) || 
                 mimeType.includes('heic') || 
                 mimeType.includes('heif');

  const idempotencyKey = `gdrive_${fileId}`;
  const ext = fileName.split('.').pop().toLowerCase();
  const isVideo = ['mp4', 'mov', 'avi', 'mkv', 'webm'].includes(ext) ||
                  mimeType.startsWith('video/');

  const driveTimestamp = item.json.modifiedTime || item.json.createdTime || new Date().toISOString();

  results.push({
    json: {
      ...item.json,
      _asp: {
        originalFilename: fileName.replace(/'/g, "''"),
        gdriveFileId: fileId,
        mimeType: mimeType,
        fileSize: fileSize,
        isHeic: isHeic,
        isVideo: isVideo,
        needsConversion: isHeic,
        idempotencyKey: idempotencyKey,
        driveTimestamp: driveTimestamp,
        takenAt: null,
        cameraModel: null,
        gpsLat: null,
        gpsLng: null,
      }
    },
    binary: item.binary
  });
}

return results;

// ============================================================
// EXIF Metadata Extraction
// ============================================================
const items = $input.all();
const results = [];

for (const item of items) {
  if (item.json._asp.isVideo || !item.binary || !item.binary.data) {
    results.push(item);
    continue;
  }

  try {
    const ExifReader = require('exifreader');
    const buffer = await item.binary.data.toBuffer();
    const tags = ExifReader.load(buffer, { expanded: true });

    const exifGroup = tags.exif || {};
    const dateTag = exifGroup.DateTimeOriginal || exifGroup.DateTime || exifGroup.CreateDate;
    if (dateTag && dateTag.description) {
      const d = dateTag.description.replace(/^(\d{4}):(\d{2}):(\d{2})/, '$1-$2-$3');
      item.json._asp.takenAt = new Date(d).toISOString();
    }

    const modelTag = exifGroup.Model;
    if (modelTag && modelTag.description) {
      item.json._asp.cameraModel = modelTag.description;
    }

    const gps = tags.gps || {};
    if (gps.Latitude !== undefined && gps.Longitude !== undefined) {
      item.json._asp.gpsLat = gps.Latitude;
      item.json._asp.gpsLng = gps.Longitude;
    }
  } catch (e) {
    console.log('EXIF extraction failed for ' + item.json._asp.originalFilename + ': ' + e.message);
  }

  results.push(item);
}

return results;

// ============================================================
// Video Metadata Extractor
// ============================================================
const items = $input.all();
const results = [];

for (const item of items) {
  const fileName = item.json.name || item.json.fileName || 'unknown';
  const fileId = item.json.id || item.json.fileId || '';
  const mimeType = item.json.mimeType || '';
  const driveTimestamp = item.json.modifiedTime || new Date().toISOString();

  results.push({
    json: {
      ...item.json,
      _asp: {
        originalFilename: fileName.replace(/'/g, "''"),
        gdriveFileId: fileId,
        mimeType: mimeType,
        fileSize: item.json.size || 0,
        isHeic: false,
        isVideo: true,
        needsConversion: false,
        idempotencyKey: `gdrive_${fileId}`,
        driveTimestamp: driveTimestamp,
        takenAt: null,
        cameraModel: null,
        gpsLat: null,
        gpsLng: null,
      }
    },
    binary: item.binary
  });
}

return results;
